const CACHE='cv-demo-v15';
self.addEventListener('install',event=>event.waitUntil((async()=>{const files=await fetch('offline-assets.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Asset list unavailable');return r.json()});const cache=await caches.open(CACHE);await cache.addAll(files);await self.skipWaiting()})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('cv-demo-')&&key!==CACHE)await caches.delete(key);await self.clients.claim()})()));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith((async()=>{const cache=await caches.open(CACHE);let cached=await cache.match(event.request,{ignoreSearch:true});if(!cached&&event.request.mode==='navigate')cached=await cache.match('index.html');if(!cached)return fetch(event.request);const range=event.request.headers.get('range');if(range&&cached.status===200){const buffer=await cached.arrayBuffer(),size=buffer.byteLength,match=/^bytes=(\d*)-(\d*)$/.exec(range);if(!match)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${size}`}});const start=match[1]?Number(match[1]):Math.max(0,size-Number(match[2]));const end=match[1]?(match[2]?Math.min(Number(match[2]),size-1):size-1):size-1;if(start>end||start>=size)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${size}`}});return new Response(buffer.slice(start,end+1),{status:206,headers:{'Content-Type':cached.headers.get('Content-Type')||'video/mp4','Content-Length':String(end-start+1),'Content-Range':`bytes ${start}-${end}/${size}`,'Accept-Ranges':'bytes'}})}return cached})())});
